    id: "hauptgruppe",
    term: "Hauptgruppe",
    aliases: [],
    definition: "Eine besondere [[Gruppe]] für Personen mit Leitungsfunktion (z. B. Dirigenten, Chorleiter, Vorstand), die bei der Ersteinrichtung einer Instanz automatisch angelegt wird. Sie kann nicht gelöscht werden, ihre Mitglieder erhalten automatisch erweiterte Rechte (Rolle [[Verantwortlicher]]) und sie erscheint nicht in Notenteil- oder Instrumentenlisten.",
  ),
  GlossaryTerm(
    id: "werk",
    term: "Werk",
    aliases: ["Stück", "Song", "Titel"],
    definition: "Ein Musikstück in der Werke-Bibliothek, mit Nummer, Namen, Schwierigkeitsgrad, Kategorien und ggf. hinterlegten Notendateien je Gruppe/Stimme.",
  ),
  GlossaryTerm(
    id: "historie",
    term: "Historie",
    aliases: [],
    definition: "Aufzeichnung, welches [[Werk]] bei welchem Termin gespielt wurde und wer die Leitung (Dirigent/Chorleiter) hatte. Grundlage für \"zuletzt gespielt\"-Angaben und Dirigenten-Auswahl im [[Ablaufplan]].",
  ),
  GlossaryTerm(
    id: "checkliste",
    term: "Checkliste",
    aliases: [],
    definition: "Liste von Aufgaben, die zu einem Termin erledigt werden müssen (z. B. \"Noten mitbringen\"), optional mit einer Frist relativ zum Termin (z. B. \"1 Tag vorher\").",
  ),
  GlossaryTerm(
    id: "organisation",
    term: "Organisation",
    aliases: [],
    definition: "Verbindet mehrere Instanzen (z. B. mehrere Chöre eines Dachvereins) miteinander, damit organisationsweite Ablaufpläne, eine gemeinsame Werke-Bibliothek und gemeinsame Personen-Zusatzfelder genutzt werden können.",
  ),
  GlossaryTerm(
    id: "zusatzfeld",
    term: "Zusatzfeld",
    aliases: ["Extra-Feld"],
    definition: "Ein frei definierbares zusätzliches Datenfeld (Text, Zahl, Datum, Ja/Nein, Auswahl) für Personen oder Werke. Personenfelder können nur für eine Instanz oder organisationsweit angelegt werden; organisationsweite Werte werden für dieselbe Person in allen verbundenen Instanzen gemeinsam verwendet.",
  ),
  GlossaryTerm(
    id: "teamorganisation",
    term: "Teamorganisation",
    aliases: [],
    definition: "Werkzeuge für Sitzungen von Vorstand oder Leitungsteam: [[Themenspeicher]], Tagesordnung im [[Ablaufplan]], Protokoll und Aufgaben. Sichtbar, sobald bei mindestens einem Termintyp „Protokoll & Tagesordnung“ eingeschaltet ist; zu finden unter Mehr → Planung.",
  ),
  GlossaryTerm(
    id: "top",
    term: "TOP",
    aliases: ["Tagesordnungspunkt", "Tagesordnungspunkte"],
    definition: "Tagesordnungspunkt: ein Thema aus dem [[Themenspeicher]], das als eigener Punkt mit Uhrzeit, Dauer und Verantwortlichem im [[Ablaufplan]] eines Termins steht. Im Protokoll hält die Leitung zu jedem TOP das Ergebnis fest (besprochen, beschlossen, vertagt).",
  ),
  GlossaryTerm(
    id: "themenspeicher",
    term: "Themenspeicher",
    aliases: [],
    definition: "Liste der offenen Themen in der [[Teamorganisation]], die noch besprochen werden sollen. Die Leitung legt Themen an oder übernimmt Vorschläge von Mitgliedern und plant sie als [[TOP]] in einen Termin ein.",
  ),
  GlossaryTerm(
    id: "protokoll-freigeben",
    term: "Protokoll freigeben",
    aliases: ["Freigabe", "freigegeben"],
    definition: "Macht ein Protokoll für den [[Personenkreis]] des Termintyps lesbar und benachrichtigt Anwesende und Personen mit Aufgaben aus der Sitzung. Vorher ist es ein Entwurf, den nur die Leitung sieht.",
  ),
  GlossaryTerm(
    id: "personenkreis",
    term: "Personenkreis",
    aliases: [],
    definition: "Alle Personen in den relevanten Gruppen eines Termintyps mit „Protokoll & Tagesordnung“ (ohne Gruppen: alle Mitglieder), außer Eltern und Bewerbern. Sie lesen freigegebene Protokolle und dürfen Themen vorschlagen.",
  ),
  GlossaryTerm(
    id: "dienst-modus",
    term: "Dienst-Modus",
    aliases: ["Dienstplan", "Dienst"],
    definition: "Einstellung eines Termintyps für Dienste wie Tontechnik: Pro Termin werden nur so viele Personen gebraucht wie eingestellt. Die Leitung teilt ein oder man trägt sich selbst ein; nur Eingeteilte zählen für die Quote.",
  ),
  GlossaryTerm(
    id: "springer",
    term: "Springer",
    aliases: ["Springerin", "Einspringer"],
    definition: "Person aus dem Dienst-Team, die bei einem Dienst nicht eingeteilt ist. Springer bekommen eine Nachricht, wenn jemand ausfällt, und können den Dienst übernehmen.",
  ),
  GlossaryTerm(
    id: "regelmaessig-verhindert",
    term: "Regelmäßig verhindert",
    aliases: ["Verfügbarkeit"],
    definition: "Regel, an welchen Wochentagen eine Person grundsätzlich nicht kann. Neue Termine an diesen Tagen werden automatisch als entschuldigt eingetragen.",
  ),
];
